using RecursiveAI.OneMedia.Codecs;

namespace RecursiveAI.OneMedia.Tests.Avi;

/// <summary>The small AVI and DV files written by an independent muxer (testdata/avi, regenerated by tools/gen-avi-testdata.sh).</summary>
public class FixtureTests
{
    private static string Fixture(string name) => System.IO.Path.Combine(AppContext.BaseDirectory, "testdata", "avi", name);

    [Theory]
    [InlineData("mjpeg-pcm.avi", "mjpeg", "pcm", 5)]
    [InlineData("mpeg4-mp3.avi", "mpeg4", "mp3", 5)]
    [InlineData("tagged.avi", "mpeg4", "mp3", 5)]
    public void MuxerWrittenAviOpensWithBothTracksAndEveryVideoFramePresent(string name, string video, string audio, int frames)
    {
        using MediaFile media = Media.Open(Fixture(name));
        Assert.Equal(MediaFormatId.Avi, media.Format);
        Assert.Equal(video, media.Video!.Codec.Name);
        Assert.Equal(audio, media.Audio!.Codec.Name);
        int n = 0;
        foreach (OwnedPacket p in media.Packets(media.Video))
        {
            using (p)
            {
                n++;
            }
        }

        Assert.Equal(frames, n);
        Assert.Empty(media.Defects);
    }

    // AVI has no avcC; the string comes from the SPS in the first key frame, and equals what the same stream gives once remuxed to MP4
    // (ffmpeg 8.0.1: profile Constrained Baseline, level 3.0).
    [Fact]
    public void H264InAviGetsItsRfc6381StringFromTheStream()
    {
        using MediaFile media = Media.Open(Fixture("h264.avi"));
        Assert.Equal("avc1.42C01E", media.Video!.Rfc6381Codec());
    }

    // ffmpeg -c copy from an MP4 leaves the avcC record after the BITMAPINFOHEADER; the string is the MP4's, not one derived from the SPS.
    [Fact]
    public void H264InAviWithAvcCGetsTheSameStringAsTheSourceMp4()
    {
        using MediaFile avi = Media.Open(Fixture("avcc.avi"));
        using MediaFile mp4 = Media.Open(Fixture("avcc-source.mp4"));
        Assert.False(avi.Video!.Configuration.IsEmpty);
        Assert.NotNull(mp4.Video!.Rfc6381Codec());
        Assert.Equal(mp4.Video!.Rfc6381Codec(), avi.Video!.Rfc6381Codec());
        Assert.NotNull(avi.Video!.DescribeCodec());
        Assert.Equal(mp4.Video!.DescribeCodec()!.Profile, avi.Video!.DescribeCodec()!.Profile);
        Assert.Equal(mp4.Video!.DescribeCodec()!.Level, avi.Video!.DescribeCodec()!.Level);
    }

    // RIFF pads a chunk to an even size: a 37-byte record (biSize 77) sits in a 78-byte strf whose last byte is the pad, which is not part of the record.
    [Fact]
    public void AnAvcCRecordOfOddLengthIsReadDespiteTheRiffPadByte()
    {
        byte[] bytes = File.ReadAllBytes(Fixture("avcc-odd.avi"));
        int strf = bytes.AsSpan().IndexOf("strf"u8);
        Assert.True(strf > 0);
        uint chunkSize = System.Buffers.Binary.BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(strf + 4));
        uint biSize = System.Buffers.Binary.BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(strf + 8));
        Assert.Equal(0u, chunkSize % 2);
        Assert.Equal(1u, biSize % 2); // the fixture really has the padded form

        using MediaFile avi = Media.Open(Fixture("avcc-odd.avi"));
        using MediaFile mp4 = Media.Open(Fixture("avcc-odd-source.mp4"));
        Assert.NotNull(avi.Video!.Rfc6381Codec());
        Assert.Equal(mp4.Video!.Rfc6381Codec(), avi.Video!.Rfc6381Codec());
        Assert.Equal(mp4.Video!.DescribeCodec()!.Profile, avi.Video!.DescribeCodec()!.Profile);
    }

    // The SPS timing counts half-frame ticks (20/2 for 10 fps); the rate is given in lowest terms, in AVI and MP4 alike.
    [Theory]
    [InlineData("h264.avi")]
    [InlineData("avcc.avi")]
    [InlineData("avcc-source.mp4")]
    public void VuiFrameRatesAreInLowestTerms(string name)
    {
        using MediaFile media = Media.Open(Fixture(name));
        CodecParameters p = media.Video!.DescribeCodec()!;
        Assert.Equal(10, p.FrameRateNumerator);
        Assert.Equal(1, p.FrameRateDenominator);
    }

    [Fact]
    public void InfoTagsAndDateAreRead()
    {
        using MediaFile media = Media.Open(Fixture("tagged.avi"));
        Assert.Equal("Test title", media.Tags.Title);
        Assert.Equal("Test artist", media.Tags.Artist);
        Assert.Equal("A comment", media.Tags.Comment);
        Assert.Equal(new DateTime(2021, 6, 5), media.CaptureTime.Candidates[0].Value.Value);
    }

    [Fact]
    public void RawDvAndDvInAviCarryTheSameRecordingTime()
    {
        foreach (string name in new[] { "one-frame-pal.dv", "one-frame-pal-type1.avi" })
        {
            using MediaFile media = Media.Open(Fixture(name));
            Assert.Equal("dvvideo", media.Video!.Codec.Name);
            Assert.Equal(new DateTime(2019, 3, 4, 5, 6, 7), media.CaptureTime.Candidates[0].Value.Value);
            using OwnedPacket p = Assert.Single(media.Packets(media.Video).ToList());
            Assert.Equal(144000, p.Data.Length);
        }
    }
}
